//============================================================
// tb_lenet5_full_conv1_v3.v
// Step 8a: FULL conv1 layer (4704 outputs) exact-compare against
// RTL-equivalent golden (generated by gen_conv1_golden_v3.py).
//
// Extends Step 7b (tb_lenet5_single_v3.v, 220 captures) to the
// entire conv1 output volume (6 channels x 28 x 28 = 4704).
// All other tb infrastructure unchanged (boot protocol via wr_*
// port, bias_redistribute workaround, plusargs).
//
// Tests:
//   T1 boot protocol (full host wr_* sequence)
//        T1.1 cfg_valid=0 after reset
//        T1.2 cfg_valid=1 after commit, drift=0
//        T1.3 all 10 cfg_mem entries match
//   T2 image load (28x28 via image_we)
//   T3 inference + ALL 4704 conv1 writebacks exact-compare
//        T3.1 4704 writebacks captured
//        T3.2 all 4704 match golden
//        T3.3 non-zero arithmetic exercised (FAIL if all zero)
//
// Expected: Model A=1353 non-zero / Model B=1449 non-zero in 4704
// (from gen_conv1_golden_v3 outputs).
//
// Compile + run identical to Step 7b — same plusargs:
//   +DATA_DIR / +COMMON_DIR / +IMG / +GOLDEN
//============================================================

`timescale 1ns/1ps

module tb_lenet5_full_conv1_v3;

    localparam integer K           = 25;
    localparam integer DATA_W      = 8;
    localparam integer FADDR_W     = 13;
    localparam integer OADDR_W     = 13;
    localparam integer WADDR_W     = 16;

    // Conv1 output sizing (must match conv_engine.v conv1 params)
    localparam integer CONV1_OUT_CH = 6;
    localparam integer CONV1_OUT_H  = 28;
    localparam integer CONV1_OUT_W  = 28;
    localparam integer CONV1_OUT_N  = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W; // 4704

    // ---- plusargs ------------------------------------------------
    reg [8*512-1:0] data_dir;
    reg [8*512-1:0] common_dir;
    reg [8*512-1:0] img_file;
    reg [8*512-1:0] golden_file;
    integer have_data, have_common, have_img, have_golden;

    function [8*512-1:0] trim(input [8*512-1:0] s);
        integer k;
        reg     started;
        reg [7:0] ch;
        begin
            trim    = {(8*512){1'b0}};
            started = 1'b0;
            for (k = 8*512-1; k >= 0; k = k - 8) begin
                ch = s[k -: 8];
                if (!started && ch != 8'h00) started = 1'b1;
                if (started) begin
                    trim = trim << 8;
                    trim[7:0] = ch;
                end
            end
        end
    endfunction

    // ---- Clock + reset -------------------------------------------
    reg clk = 0;
    reg rst_n = 0;
    always #5 clk = ~clk;

    // ---- DUT I/O -------------------------------------------------
    reg                       start;
    reg                       image_we;
    reg  [FADDR_W-1:0]        image_addr;
    reg  signed [DATA_W-1:0]  image_data;
    reg                       cfg_wr_en;
    reg  [5:0]                cfg_wr_addr;
    reg  [31:0]               cfg_wr_data;
    wire                      done;
    wire [3:0]                predicted_class;

    lenet5_top #(
        .DATA_DIR(""),
        .COMMON_DIR("")
    ) DUT (
        .clk(clk), .rst_n(rst_n),
        .start(start),
        .done(done),
        .predicted_class(predicted_class),
        .image_we(image_we),
        .image_addr(image_addr),
        .image_data(image_data),
        .cfg_wr_en(cfg_wr_en),
        .cfg_wr_addr(cfg_wr_addr),
        .cfg_wr_data(cfg_wr_data)
    );

    // ---- Mirrors -------------------------------------------------
    reg signed [DATA_W-1:0] image_mirror  [0:783];
    reg          [7:0]      golden_mirror [0:CONV1_OUT_N-1];
    reg          [31:0]     cfg_words     [0:9];   // 10 layer_config entries

    // ---- Multi-writeback capture (full conv1) --------------------
    // Capture all CONV1_OUT_N=4704 writebacks. Both models produce
    // 1300+ non-zero outputs (gen_conv1_golden stats):
    //   Model A: 1353 non-zero / 4704
    //   Model B: 1449 non-zero / 4704
    // Measured ~41 cycles per writeback in Step 7b → expect
    // ~193K cycles inference. Inner timeout = 250000 cycles.
    localparam integer N_CAPTURE = 4704;

    reg            capture_done = 1'b0;
    integer        cap_count    = 0;
    reg [OADDR_W-1:0] cap_addr [0:N_CAPTURE-1];
    reg signed [DATA_W-1:0] cap_data [0:N_CAPTURE-1];

    always @(posedge clk) begin
        if (!rst_n) begin
            capture_done <= 1'b0;
            cap_count    <= 0;
        end else if (DUT.fbuf_write_en_fsm && !capture_done) begin
            cap_addr[cap_count] <= DUT.fbuf_write_addr_fsm;
            cap_data[cap_count] <= DUT.fbuf_write_data_fsm;
            if (cap_count == N_CAPTURE - 1) begin
                capture_done <= 1'b1;
            end
            cap_count <= cap_count + 1;
        end
    end

    // ---- Stats ---------------------------------------------------
    integer pass_count = 0;
    integer fail_count = 0;

    //==========================================================
    // Boot helpers
    //==========================================================
    task do_cfg_write(input [5:0] a, input [31:0] d);
        begin
            @(negedge clk);
            cfg_wr_en   = 1'b1;
            cfg_wr_addr = a;
            cfg_wr_data = d;
            @(negedge clk);
            cfg_wr_en   = 1'b0;
        end
    endtask

    //==========================================================
    // Hierarchical $readmemh macros
    //==========================================================
    `define LOAD_SRAM_DEC_LANE(I) \
        $readmemh({trim(data_dir), "/addr_to_slot_conv1_sram.hex"}, DUT.u_imc.sram_dec[I].U_SDEC.rom_conv1); \
        $readmemh({trim(data_dir), "/addr_to_slot_conv2_sram.hex"}, DUT.u_imc.sram_dec[I].U_SDEC.rom_conv2); \
        $readmemh({trim(data_dir), "/addr_to_slot_fc1_sram.hex"},   DUT.u_imc.sram_dec[I].U_SDEC.rom_fc1);   \
        $readmemh({trim(data_dir), "/addr_to_slot_fc2_sram.hex"},   DUT.u_imc.sram_dec[I].U_SDEC.rom_fc2);   \
        $readmemh({trim(data_dir), "/addr_to_slot_fc3_sram.hex"},   DUT.u_imc.sram_dec[I].U_SDEC.rom_fc3);

    `define LOAD_PCM_DEC_LANE(I) \
        $readmemh({trim(data_dir), "/addr_to_slot_conv1_pcm.hex"}, DUT.u_imc.pcm_dec[I].U_PDEC.rom_conv1); \
        $readmemh({trim(data_dir), "/addr_to_slot_conv2_pcm.hex"}, DUT.u_imc.pcm_dec[I].U_PDEC.rom_conv2); \
        $readmemh({trim(data_dir), "/addr_to_slot_fc1_pcm.hex"},   DUT.u_imc.pcm_dec[I].U_PDEC.rom_fc1);   \
        $readmemh({trim(data_dir), "/addr_to_slot_fc2_pcm.hex"},   DUT.u_imc.pcm_dec[I].U_PDEC.rom_fc2);   \
        $readmemh({trim(data_dir), "/addr_to_slot_fc3_pcm.hex"},   DUT.u_imc.pcm_dec[I].U_PDEC.rom_fc3);

    task load_all_dut_memories;
        begin
            // pcm_imc_unit innards
            // NOTE: cfg_mem is NOT hierarchically preloaded here.
            // Step 7b T1 exercises the full host boot protocol by
            // driving the cfg_wr_* port for all 10 layer_config words
            // + 0x21 (drift_t) + 0x20 (commit). cfg_mem reaches its
            // populated state via the public regfile write path.
            $readmemh({trim(data_dir),   "/sram_pool.hex"},    DUT.u_imc.U_SPOOL.sram_pool_mem);
            $readmemh({trim(data_dir),   "/pcm_pool.hex"},     DUT.u_imc.U_PCB.pcm_pool);
            $readmemh({trim(data_dir),   "/nu_pcm_pool.hex"},  DUT.u_imc.U_PCB.nu_pcm_pool);
            $readmemh({trim(common_dir), "/log2_lut.hex"},     DUT.u_imc.U_PCB.log2_lut);
            $readmemh({trim(common_dir), "/exp2_lut.hex"},     DUT.u_imc.U_PCB.exp2_lut);

            // 25 SRAM + 25 PCM decoder ROMs (5 hex each)
            `LOAD_SRAM_DEC_LANE(0)  `LOAD_SRAM_DEC_LANE(1)  `LOAD_SRAM_DEC_LANE(2)
            `LOAD_SRAM_DEC_LANE(3)  `LOAD_SRAM_DEC_LANE(4)  `LOAD_SRAM_DEC_LANE(5)
            `LOAD_SRAM_DEC_LANE(6)  `LOAD_SRAM_DEC_LANE(7)  `LOAD_SRAM_DEC_LANE(8)
            `LOAD_SRAM_DEC_LANE(9)  `LOAD_SRAM_DEC_LANE(10) `LOAD_SRAM_DEC_LANE(11)
            `LOAD_SRAM_DEC_LANE(12) `LOAD_SRAM_DEC_LANE(13) `LOAD_SRAM_DEC_LANE(14)
            `LOAD_SRAM_DEC_LANE(15) `LOAD_SRAM_DEC_LANE(16) `LOAD_SRAM_DEC_LANE(17)
            `LOAD_SRAM_DEC_LANE(18) `LOAD_SRAM_DEC_LANE(19) `LOAD_SRAM_DEC_LANE(20)
            `LOAD_SRAM_DEC_LANE(21) `LOAD_SRAM_DEC_LANE(22) `LOAD_SRAM_DEC_LANE(23)
            `LOAD_SRAM_DEC_LANE(24)

            `LOAD_PCM_DEC_LANE(0)  `LOAD_PCM_DEC_LANE(1)  `LOAD_PCM_DEC_LANE(2)
            `LOAD_PCM_DEC_LANE(3)  `LOAD_PCM_DEC_LANE(4)  `LOAD_PCM_DEC_LANE(5)
            `LOAD_PCM_DEC_LANE(6)  `LOAD_PCM_DEC_LANE(7)  `LOAD_PCM_DEC_LANE(8)
            `LOAD_PCM_DEC_LANE(9)  `LOAD_PCM_DEC_LANE(10) `LOAD_PCM_DEC_LANE(11)
            `LOAD_PCM_DEC_LANE(12) `LOAD_PCM_DEC_LANE(13) `LOAD_PCM_DEC_LANE(14)
            `LOAD_PCM_DEC_LANE(15) `LOAD_PCM_DEC_LANE(16) `LOAD_PCM_DEC_LANE(17)
            `LOAD_PCM_DEC_LANE(18) `LOAD_PCM_DEC_LANE(19) `LOAD_PCM_DEC_LANE(20)
            `LOAD_PCM_DEC_LANE(21) `LOAD_PCM_DEC_LANE(22) `LOAD_PCM_DEC_LANE(23)
            `LOAD_PCM_DEC_LANE(24)

            // bias_storage flat array
            $readmemh({trim(data_dir), "/biases_all.hex"}, DUT.u_bias.flat_biases);
            // CRITICAL: bias_storage.v distributes flat_biases -> biases[L][C]
            // in a single initial block at time 0. By that time, flat_biases
            // is empty (DUT.DATA_DIR=""). After we hierarchically load
            // flat_biases above, biases[L][C] is still 0. Manually re-run
            // the distribute loop here (mirror bias_storage.v L97-101).
            // Layer offsets (cumulative): conv1=0, conv2=6, fc1=22,
            //   fc2=142, fc3=226 ; counts: 6, 16, 120, 84, 10.
            begin: bias_redistribute
                integer L, C;
                integer per_count [0:4];
                integer per_offset [0:4];
                per_count[0] = 6;    per_offset[0] = 0;
                per_count[1] = 16;   per_offset[1] = 6;
                per_count[2] = 120;  per_offset[2] = 22;
                per_count[3] = 84;   per_offset[3] = 142;
                per_count[4] = 10;   per_offset[4] = 226;
                for (L = 0; L < 5; L = L + 1) begin
                    for (C = 0; C < per_count[L]; C = C + 1) begin
                        DUT.u_bias.biases[L][C] =
                            DUT.u_bias.flat_biases[per_offset[L] + C];
                    end
                end
            end

            // layer_desc_rom rshift table
            $readmemh({trim(data_dir), "/rshift_per_layer.hex"}, DUT.u_fsm.u_rom.rshift_table);
        end
    endtask

    //==========================================================
    // Main
    //==========================================================
    integer i;
    integer wait_count;

    initial begin
        $display("============================================================");
        $display("tb_lenet5_full_conv1_v3  (Step 8a FULL conv1 layer test)");
        $display("============================================================");

        data_dir   = {(8*512){1'b0}};
        common_dir = {(8*512){1'b0}};
        img_file   = {(8*512){1'b0}};
        golden_file= {(8*512){1'b0}};
        have_data   = $value$plusargs("DATA_DIR=%s",   data_dir);
        have_common = $value$plusargs("COMMON_DIR=%s", common_dir);
        have_img    = $value$plusargs("IMG=%s",        img_file);
        have_golden = $value$plusargs("GOLDEN=%s",     golden_file);

        if (!have_data || !have_common || !have_img || !have_golden) begin
            $display("ERROR: required plusargs missing:");
            $display("  +DATA_DIR=...");
            $display("  +COMMON_DIR=...");
            $display("  +IMG=...");
            $display("  +GOLDEN=...");
            $finish;
        end
        $display("  DATA_DIR   = %0s", trim(data_dir));
        $display("  COMMON_DIR = %0s", trim(common_dir));
        $display("  IMG        = %0s", trim(img_file));
        $display("  GOLDEN     = %0s", trim(golden_file));
        $display("");

        // ---- Initialize signals ----
        start       = 0;
        image_we    = 0;
        image_addr  = 0;
        image_data  = 0;
        cfg_wr_en   = 0;
        cfg_wr_addr = 0;
        cfg_wr_data = 0;
        rst_n       = 0;

        // Hold reset, wait for first negedge to let module initial blocks settle
        @(negedge clk); @(negedge clk); @(negedge clk);

        // Load all DUT internal memories (hierarchical override)
        load_all_dut_memories();

        // Load testbench mirrors
        $readmemh(trim(img_file),    image_mirror);
        $readmemh(trim(golden_file), golden_mirror);
        $readmemh({trim(data_dir), "/layer_config.hex"}, cfg_words);

        $display("  Loaded image (784 pixels), golden (%0d entries), cfg_words (10)",
                 CONV1_OUT_N);
        $display("  image first byte = %0d", $signed(image_mirror[0]));
        $display("");

        // Deassert reset
        @(negedge clk);
        rst_n = 1;
        @(negedge clk); @(negedge clk);

        //----------------------------------------------------------
        // T1 — Boot protocol (full path through public wr_* bus)
        //----------------------------------------------------------
        $display("T1  Boot protocol (full host wr_* sequence)");
        if (DUT.u_imc.cfg_valid_dbg === 1'b0) begin
            pass_count = pass_count + 1;
            $display("  [PASS] T1.1 cfg_valid_dbg=0 after reset (no commit yet)");
        end else begin
            fail_count = fail_count + 1;
            $display("  [FAIL] T1.1 cfg_valid_dbg=%b (expected 0)",
                     DUT.u_imc.cfg_valid_dbg);
        end

        // Write the 10 layer_config words (0x00..0x09) via public port
        for (i = 0; i < 10; i = i + 1) begin
            do_cfg_write(i[5:0], cfg_words[i]);
        end

        // Write drift_t = 0 (explicit; default is 0 anyway)
        do_cfg_write(6'h21, 32'h0000_0000);

        // Commit pulse (bit1=commit, bit0=enable_drift=0)
        do_cfg_write(6'h20, 32'h0000_0002);

        // Verify regfile contents AND cfg_valid latched
        if (DUT.u_imc.cfg_valid_dbg === 1'b1 &&
            DUT.u_imc.enable_drift_dbg === 1'b0 &&
            DUT.u_imc.drift_t_dbg === 16'd0) begin
            pass_count = pass_count + 1;
            $display("  [PASS] T1.2 after commit: cfg_valid=1, enable_drift=0, drift_t=0");
        end else begin
            fail_count = fail_count + 1;
            $display("  [FAIL] T1.2 cfg_valid=%b enable_drift=%b drift_t=%0d",
                     DUT.u_imc.cfg_valid_dbg,
                     DUT.u_imc.enable_drift_dbg,
                     DUT.u_imc.drift_t_dbg);
        end

        // Spot-check that cfg_mem actually got loaded correctly via wr port
        // (compare regfile entries against our mirror)
        begin: cfg_verify
            integer cfg_idx;
            integer cfg_diffs;
            cfg_diffs = 0;
            for (cfg_idx = 0; cfg_idx < 10; cfg_idx = cfg_idx + 1) begin
                if (DUT.u_imc.U_REGFILE.cfg_mem[cfg_idx] !== cfg_words[cfg_idx]) begin
                    cfg_diffs = cfg_diffs + 1;
                    $display("    [DIFF] cfg_mem[%0d]=%h  expected=%h",
                             cfg_idx,
                             DUT.u_imc.U_REGFILE.cfg_mem[cfg_idx],
                             cfg_words[cfg_idx]);
                end
            end
            if (cfg_diffs == 0) begin
                pass_count = pass_count + 1;
                $display("  [PASS] T1.3 all 10 cfg_mem entries match (wr port worked)");
            end else begin
                fail_count = fail_count + 1;
                $display("  [FAIL] T1.3 %0d / 10 cfg_mem mismatches", cfg_diffs);
            end
        end

        //----------------------------------------------------------
        // T2 — Image load
        //----------------------------------------------------------
        $display("");
        $display("T2  Image loading (28x28 = 784 pixels via image_we)");
        for (i = 0; i < 784; i = i + 1) begin
            @(negedge clk);
            image_we   = 1'b1;
            image_addr = i[FADDR_W-1:0];
            image_data = image_mirror[i];
        end
        @(negedge clk);
        image_we   = 1'b0;
        image_addr = 0;
        image_data = 0;

        // Quick sanity: verify feature_buffer has correct first pixel
        // (feature_buffer.A_mem[0] — adjust if internal name differs)
        // Skip detailed verification; correctness is tested transitively
        // by T3 conv1 output match.
        pass_count = pass_count + 1;
        $display("  [PASS] T2.1 784 pixels written");

        //----------------------------------------------------------
        // T3 — Inference + first N=300 conv1 writebacks
        //----------------------------------------------------------
        $display("");
        $display("T3  Inference start + first %0d conv1 writebacks", N_CAPTURE);

        @(negedge clk);
        start = 1'b1;
        @(negedge clk);
        start = 1'b0;

        // Wait for capture_done or generous timeout
        // (~41 cyc/write * 4704 ≈ 193K cycles; allow 250K for safety)
        wait_count = 0;
        while (!capture_done && wait_count < 250000) begin
            @(negedge clk);
            wait_count = wait_count + 1;
        end

        if (!capture_done) begin
            fail_count = fail_count + 1;
            $display("  [FAIL] T3.1 only %0d/%0d writebacks captured in %0d cycles",
                     cap_count, N_CAPTURE, wait_count);
        end else begin
            pass_count = pass_count + 1;
            $display("  [PASS] T3.1 %0d writebacks captured in %0d cycles (avg %0d cyc/write)",
                     N_CAPTURE, wait_count, wait_count / N_CAPTURE);

            // Compare every capture against golden
            begin: compare_block
                integer mismatches;
                integer nonzero_count;
                integer first_mismatch;
                integer cap_idx;
                integer abs_diff;
                integer max_abs_diff;
                reg [7:0] exp_val;
                reg [OADDR_W-1:0] addr;
                mismatches     = 0;
                nonzero_count  = 0;
                first_mismatch = -1;
                max_abs_diff   = 0;
                for (cap_idx = 0; cap_idx < N_CAPTURE; cap_idx = cap_idx + 1) begin
                    addr    = cap_addr[cap_idx];
                    exp_val = golden_mirror[addr];
                    if (exp_val != 0) nonzero_count = nonzero_count + 1;
                    if (cap_data[cap_idx] !== $signed({1'b0, exp_val})) begin
                        // signed difference -> absolute
                        if (cap_data[cap_idx] > $signed({1'b0, exp_val}))
                            abs_diff = cap_data[cap_idx] - $signed({1'b0, exp_val});
                        else
                            abs_diff = $signed({1'b0, exp_val}) - cap_data[cap_idx];
                        if (abs_diff > max_abs_diff) max_abs_diff = abs_diff;
                        if (mismatches < 5) begin
                            $display("    [DIFF] cap[%0d] addr=%0d got=%0d exp=%0d (oc=%0d y=%0d x=%0d)",
                                     cap_idx, addr,
                                     cap_data[cap_idx], exp_val,
                                     addr / (CONV1_OUT_H * CONV1_OUT_W),
                                     (addr / CONV1_OUT_W) % CONV1_OUT_H,
                                     addr % CONV1_OUT_W);
                        end
                        if (first_mismatch < 0) first_mismatch = cap_idx;
                        mismatches = mismatches + 1;
                    end
                end

                if (mismatches == 0) begin
                    pass_count = pass_count + 1;
                    $display("  [PASS] T3.2 all %0d writebacks match golden",
                             N_CAPTURE);
                end else begin
                    fail_count = fail_count + 1;
                    $display("  [FAIL] T3.2 %0d / %0d mismatches (first at idx=%0d, max_abs_diff=%0d)",
                             mismatches, N_CAPTURE, first_mismatch, max_abs_diff);
                end

                // Sanity: arithmetic exercised (non-zero golden cases compared)
                if (nonzero_count == 0) begin
                    fail_count = fail_count + 1;
                    $display("  [FAIL] T3.3 all %0d captured golden entries are zero -- arithmetic not exercised",
                             N_CAPTURE);
                end else begin
                    pass_count = pass_count + 1;
                    $display("  [PASS] T3.3 %0d non-zero golden compares (arithmetic exercised)",
                             nonzero_count);
                end

                // Sample captures across the full window for visibility
                $display("");
                $display("  Sample captures (spread across 4704):");
                $display("    cap[0]:    addr=%0d  got=%0d  exp=%0d",
                         cap_addr[0],    cap_data[0],    golden_mirror[cap_addr[0]]);
                $display("    cap[1000]: addr=%0d  got=%0d  exp=%0d",
                         cap_addr[1000], cap_data[1000], golden_mirror[cap_addr[1000]]);
                $display("    cap[2000]: addr=%0d  got=%0d  exp=%0d",
                         cap_addr[2000], cap_data[2000], golden_mirror[cap_addr[2000]]);
                $display("    cap[3000]: addr=%0d  got=%0d  exp=%0d",
                         cap_addr[3000], cap_data[3000], golden_mirror[cap_addr[3000]]);
                $display("    cap[%0d]: addr=%0d  got=%0d  exp=%0d",
                         N_CAPTURE-1,
                         cap_addr[N_CAPTURE-1],
                         cap_data[N_CAPTURE-1],
                         golden_mirror[cap_addr[N_CAPTURE-1]]);
            end
        end

        //----------------------------------------------------------
        // Summary
        //----------------------------------------------------------
        $display("");
        $display("============================================================");
        $display("Total: %0d passed, %0d failed", pass_count, fail_count);
        if (fail_count == 0) begin
            $display("RESULT: ALL TESTS PASSED");
        end else begin
            $display("RESULT: FAILED");
        end
        $display("============================================================");

        $finish;
    end

    initial begin
        #50000000;
        $display("[FAIL] simulation timeout");
        $finish;
    end

endmodule
